/* @prim:begin 66-give-get-table */
.gg { display: flex; flex-direction: column; background: var(--surface); border: 1px solid var(--border); border-radius: var(--ds-r-md); overflow: hidden; }
.gg-row { display: grid; grid-template-columns: 5.5rem minmax(0, 1fr) minmax(0, 1fr); column-gap: var(--sp-3, 24px); padding: var(--sp-2, 16px) var(--sp-3, 24px); border-top: 1px solid var(--border); }
.gg-head { padding: var(--sp-1, 8px) var(--sp-3, 24px); background: var(--surface-2); border-top: 0; border-bottom: 1px solid var(--border); font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; color: var(--muted); }
.gg-head .get { color: var(--cyan); }
.gg-head + .gg-row { border-top: 0; }
.gg-when { font-weight: 600; color: var(--text); }
.gg-give { color: var(--text-secondary); text-wrap: pretty; }
.gg-give > span { display: block; }
.gg-give > span + span { margin-top: 4px; }
.gg-get { color: var(--text); text-wrap: pretty; }
.gg .vh { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
@media (max-width: 640px) { .gg-row { grid-template-columns: minmax(0, 1fr); row-gap: 6px; } .gg-head { display: none; } .gg > .gg-row:nth-child(2) { border-top: 0; } .gg-give::before { content: "You give: "; font-weight: 600; color: var(--text); } .gg-get::before { content: "You get: "; font-weight: 600; color: var(--cyan); } }
@container (max-width: 40rem) { .gg-row { grid-template-columns: minmax(0, 1fr); row-gap: 6px; } .gg-head { display: none; } .gg > .gg-row:nth-child(2) { border-top: 0; } .gg-give::before { content: "You give: "; font-weight: 600; color: var(--text); } .gg-get::before { content: "You get: "; font-weight: 600; color: var(--cyan); } }
@media print { .gg { background: none; border-width: 0; border-radius: 0; break-inside: avoid; } .gg-head { background: none; padding: 0 0 6px; border-bottom: 1.5px solid var(--text); } .gg-row { grid-template-columns: 4.5rem minmax(0, 1fr) minmax(0, 1fr); column-gap: var(--sp-2, 16px); padding: 8px 0; line-height: 1.38; } }
/* @prim:end 66-give-get-table */

