function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var GG=[['Before',['Mutual NDA; total figures only.'],'Customer-level data stays with you.'],['Week 1',['Kickoff, 60 min.','Screen-share with your data lead, 90 min.'],'Both decisions written up.'],['Week 2',['Readout, 60 min, and your pushback.'],'The rest, with your pushback on the page.']];
function kitGG(host,n){var w=document.createElement('div');w.className='gg';w.setAttribute('role','table');w.setAttribute('aria-label','What you give and what you get');w.innerHTML='<div class="gg-row gg-head" role="row"><span role="columnheader"><span class="vh">When</span></span><span role="columnheader">What you give</span><span role="columnheader" class="get">What you get</span></div>'+GG.slice(0,n).map(function(r){return '<div class="gg-row" role="row"><span class="gg-when" role="rowheader">'+kEsc(r[0])+'</span><span class="gg-give" role="cell">'+(r[1].length>1?r[1].map(function(x){return '<span>'+kEsc(x)+'</span>'}).join(''):kEsc(r[1][0]))+'</span><span class="gg-get" role="cell">'+kEsc(r[2])+'</span></div>'}).join('');host.appendChild(w);return w}
kitGG(kSlot(),3);
STATES.forEach(function(a,i){var b=document.createElement('div');b.style.maxWidth=a[1];if(a[1]!=='100%')b.style.containerType='inline-size';kSlot(i).appendChild(b);kitGG(b,a[0])});
